      "path": "dsh/runtime/src/tool-runtime.mts",
      "content": "import { leadState, leadTaskId, leadGap, isLeadWriteTool } from \"./lead-mode.mjs\";\nimport { classifyPendingReviewerText } from \"./router.mjs\";\nimport { extractLatestUserText } from \"./router.mjs\";\nimport { createRepeatedFailureMonitor } from \"./repeated-failure.mjs\";\nimport { DEFAULT_CHILD_ALLOWED_TOOLS, DEFAULT_PROTECTED_CONTROLLER_ALLOWED_TOOLS, activeRouteProtection, createChildToolGuard, createRouteProtectionGuard, isSubagent, summarizeToolResult } from \"./governance.mjs\";\nimport { createRoutingConfigTool, effectiveRoutingSnapshot } from \"./routing-config.mjs\";\nimport { createOutputConfigTool } from \"./output-config.mjs\";\nimport type { OutputPolicy } from \"./output-config.mjs\";\nimport { createCanonicalReferenceTool } from \"./canonical-reference.mjs\";\nimport { createCompactionConfigTool } from \"./compaction-config.mjs\";\nimport { ODAI_CORE_TOOL_NAMES, activeOdaiToolNames, inactiveOdaiToolNames } from \"./context-activation.mjs\";\nimport type { ContextActivation } from \"./context-activation.mjs\";\nimport { createContextCapabilityTool } from \"./context-capability.mjs\";\nimport { createHumanCareTool } from \"./human-care.mjs\";\nimport { createHumanSafetyTool } from \"./human-safety.mjs\";\nimport { createHumanSafetyContinuityTool } from \"./human-safety-continuity.mjs\";\nimport { bindResponsibilityGapToTask, createResponsibilityGapTool } from \"./responsibility-gap.mjs\";\nimport type { RequirementSourceCandidate, ResponsibilityGapProposal } from \"./responsibility-gap.mjs\";\nimport { createResponsibilityReturnTool } from \"./responsibility-return.mjs\";\nimport type { ResponsibilityReturnResult } from \"./responsibility-return.mjs\";\nimport type { ResponsibilityScopeOwner } from \"./responsibility-scope.mjs\";\nimport { createSkillSourceConfigTool } from \"./skill-source-config.mjs\";\nimport { createSemanticMemoryTool, latestDirectUserMessage } from \"./semantic-memory.mjs\";\nimport { readSkillBundleFile } from \"./skill-bundle.mjs\";\nimport type { SkillBundle } from \"./skill-bundle.mjs\";\nimport { currentAgentTurn, sharedSkillSelection } from \"./skill-selection-state.mjs\";\nimport { currentAgentStep, isSubagentSession, isManagedRoleChild, routedRoleOf, latestRouteReceipt, pluginMessage, managedReviewEvidenceReader } from \"./runtime-support.mjs\";\nimport { createReviewEvidenceTool } from \"./review-evidence.mjs\";\nimport type { SkillSelection } from \"./runtime-support.mjs\";\nimport type { DshAgent, DshEvent, DshMessage, DshRuntimeContext, ModelRoute, RuntimeConfig, RuntimeEventData, RuntimeLogger, ToolExecution, ToolResult, UnknownRecord } from \"./runtime-types.mjs\";\nimport { isUnknownRecord, sessionEvents } from \"./runtime-types.mjs\";\n\ninterface RouteProtection extends UnknownRecord { scopeId?: string }\ninterface ExposureOptions { turn?: number; step?: number; responsibilityReturn?: boolean }\ntype ExecutionRestriction = import(\"./runtime-types.mjs\").ToolRestriction;\ninterface PromptInstaller { install(deps: { pendingResponsibilityGap: ToolRuntimeDependencies[\"pendingResponsibilityGap\"]; executionRestrictionFor: (agent: DshAgent) => ExecutionRestriction; syncToolExposure: (agent: DshAgent, activation: ContextActivation, options: { turn?: number; step: number; responsibilityReturn: boolean }) => readonly string[] }): void }\ninterface ToolRuntimeDependencies {\n  appendEvent(agent: DshAgent, type: string, data: object): void;\n  bundled: SkillBundle;\n  config: RuntimeConfig;\n  ctx: DshRuntimeContext;\n  evidence: { events(agent: DshAgent): DshEvent[] };\n  explicitSkillPath: boolean;\n  hasSessionEvent(agent: DshAgent, type: string, predicate: (data: RuntimeEventData) => boolean): boolean;\n  humanSafetyContinuityStorePath: string;\n  logger: RuntimeLogger;\n  pendingResponsibilityGap(agent: DshAgent, turn: number | undefined, step: number): ResponsibilityGapProposal | undefined;\n  promptRuntime: PromptInstaller;\n  responsibilityRoutingFor(agent: DshAgent, turn?: number): boolean;\n  responsibilityScopes: Pick<ResponsibilityScopeOwner, \"get\" | \"has\" | \"stop\">;\n  routeProtections: WeakMap<DshAgent, RouteProtection>;\n  selectOutputForAgent(): { policy: OutputPolicy };\n}\n\nexport function installToolRuntime(deps: ToolRuntimeDependencies): void {\n  const { appendEvent, bundled, config, ctx, evidence, explicitSkillPath, hasSessionEvent, humanSafetyContinuityStorePath, logger, pendingResponsibilityGap, promptRuntime, responsibilityRoutingFor, responsibilityScopes, selectOutputForAgent } = deps;\n  const { stop: stopResponsibilityScope } = responsibilityScopes;\n  const onDenied = (execution: ToolExecution & { agent: DshAgent }, reason: string) => {\n    appendEvent(execution.agent, \"odai/governance-denied\", {\n      callId: String(execution.callId),\n      tool: execution.name,\n      reason,\n    });\n  };\n  const childGuard = createChildToolGuard({\n    additionalDeniedTools: config.governance.additionalDeniedTools,\n    onDenied,\n  });\n  // Scope policy, model mapping and dispatch are separate inputs. Only the\n  // authenticated scope owner can restrict an in-place responsibility; a pending\n  // gap or a matching word in the user's request cannot change permissions.\n  const isReadOnlyResponsibility = (agent: DshAgent | undefined): boolean => Boolean(agent\n    && responsibilityScopes.get(agent)?.continuationPolicy === \"read-only-tool-chain\");\n  const reviewerAllowedTools = Object.freeze([\"odai_review_evidence\", \"read\", \"glob\", \"grep\"]);\n  const isManagedReviewer = (agent: DshAgent): boolean =>\n    isManagedRoleChild(agent) && routedRoleOf(agent) === \"reviewer\";\n  const protectionFor = (agent: DshAgent) => config.routing.mode === \"off\"\n    ? undefined\n    : activeRouteProtection(agent, evidence.events(agent));\n  const executionRestrictionFor = (agent: DshAgent): ExecutionRestriction => {\n    const allow = isSubagentSession(agent)\n      ? isManagedReviewer(agent) ? reviewerAllowedTools : DEFAULT_CHILD_ALLOWED_TOOLS\n      : isReadOnlyResponsibility(agent) || protectionFor(agent) ? DEFAULT_PROTECTED_CONTROLLER_ALLOWED_TOOLS : undefined;\n    return allow ? { allow, deny: config.governance.additionalDeniedTools } : {};\n  };\n  const routeProtectionGuard = createRouteProtectionGuard({\n    additionalDeniedTools: config.governance.additionalDeniedTools,\n    onDenied,\n    isReadOnlyResponsibility,\n    protectionFor,\n  });\n  const requirementSourcesFor = (agent: DshAgent): readonly RequirementSourceCandidate[] => {\n    const sources: RequirementSourceCandidate[] = [];\n    for (const [order, event] of sessionEvents(agent.session).entries()) {\n      if (event.type !== \"user/message\") continue;\n      const message = isUnknownRecord(event.data.message) ? event.data.message : event.data;\n      const source = isUnknownRecord(message.source) ? message.source : undefined;\n      if (message.role !== \"user\" || source?.kind !== \"user\" || typeof message.id !== \"string\" || !message.id) continue;\n      const text = extractLatestUserText([message as DshMessage]);\n      if (!text) continue;\n      sources.push(Object.freeze({ messageId: message.id, text, order }));\n    }\n    return Object.freeze(sources);\n  };\n  const gapForCurrentTask = (\n    agent: DshAgent,\n    proposal: Readonly<ResponsibilityGapProposal>,\n  ): Readonly<ResponsibilityGapProposal> => {\n    const message = latestDirectUserMessage(agent);\n    if (message && typeof message.id === \"string\" && message.id) {\n      return bindResponsibilityGapToTask(proposal, message.id, requirementSourcesFor(agent));\n    }\n    if (proposal.requirements) throw new Error(\"requirement provenance needs an authenticated direct-user task message\");\n    return proposal;\n  };\n  const bundleFor = (agent: DshAgent): SkillBundle => sharedSkillSelection<SkillSelection>(agent)?.bundle ?? bundled;\n  ctx.tools.register(createReviewEvidenceTool(managedReviewEvidenceReader));\n  ctx.tools.register(createContextCapabilityTool({\n    isChild: isSubagent,\n    onRequested(agent: DshAgent, capability: string) {\n      const turn = currentAgentTurn(agent);\n      const step = currentAgentStep(agent);\n      appendEvent(agent, \"odai/context-capability-requested\", {\n        ...(turn === undefined ? {} : { turn }),\n        ...(step === undefined ? {} : { step }),\n        capability,\n      });\n    },\n  }));\n  ctx.tools.register(createCanonicalReferenceTool({\n    bundleFor,\n    isUnavailable(agent) {\n      return isSubagent(agent) || responsibilityScopes.has(agent);\n    },\n  }));\n  ctx.tools.register(createRoutingConfigTool(config.routing.configPath, {\n    configuredRoles: config.routing.roles,\n    configuredDispatch: config.routing.dispatch,\n    resolveCallConfig(route: ModelRoute, signal?: AbortSignal) {\n      return ctx.llm.resolveCallConfig(route, signal);\n    },\n    latestRouteFor(agent: DshAgent) {\n      return latestRouteReceipt(evidence.events(agent));\n    },\n    outputPolicyFor() {\n      return selectOutputForAgent().policy;\n    },\n    onConfigured(agent, data) {\n      appendEvent(agent, \"odai/routing-configured\", data);\n    },\n  }));\n  ctx.tools.register(createHumanCareTool({\n    isChild: isSubagent,\n    contractFor(agent: DshAgent) {\n      const bundle = bundleFor(agent);\n      return readSkillBundleFile(bundle, bundle.manifest.referenceFiles.care).toString(\"utf8\");\n    },\n  }));\n  ctx.tools.register(createHumanSafetyTool({\n    isChild: isSubagent,\n    contractFor(agent: DshAgent) {\n      const bundle = bundleFor(agent);\n      return readSkillBundleFile(bundle, bundle.manifest.referenceFiles[\"human-safety\"]).toString(\"utf8\");\n    },\n  }));\n  ctx.tools.register(createResponsibilityGapTool({\n    isChild: isSubagent,\n    bindToTask: gapForCurrentTask,\n    onProposed(agent: DshAgent, proposal: RuntimeEventData) {\n      const turn = currentAgentTurn(agent);\n      const step = currentAgentStep(agent);\n      appendEvent(agent, \"odai/responsibility-gap\", {\n        ...(turn === undefined ? {} : { turn }),\n        ...(step === undefined ? {} : { step }),\n        ...proposal,\n      });\n    },\n  }));\n  ctx.tools.register(createResponsibilityReturnTool({\n    activeScopeFor(agent) {\n      return responsibilityScopes.get(agent);\n    },\n    onReturned(agent, result: ResponsibilityReturnResult) {\n      const turn = currentAgentTurn(agent);\n      const step = currentAgentStep(agent);\n      const stopped = stopResponsibilityScope(agent, \"responsibility-returned\", {\n        ...(step === undefined ? {} : { step }),\n        scopeId: result.scopeId,\n      });\n      if (!stopped) throw new Error(`responsibility scope ${result.scopeId} is no longer active`);\n      appendEvent(agent, \"odai/responsibility-returned\", {\n        ...(turn === undefined ? {} : { turn }),\n        ...(step === undefined ? {} : { step }),\n        ...result,\n      });\n    },\n  }));\n  ctx.tools.register(createSkillSourceConfigTool(\n    config.governance.skillConfigPath,\n    config.governance.skillSource,\n    {\n      explicitPath: explicitSkillPath,\n      onConfigured(agent, data) {\n        appendEvent(agent, \"odai/skill-source-configured\", data);\n      },\n    },\n  ));\n  ctx.tools.register(createOutputConfigTool(config.output.configPath, {\n    isChild: isSubagent,\n    responsibilityRoutesFor() {\n      try {\n        return effectiveRoutingSnapshot(config.routing.configPath, config.routing.roles, config.routing.dispatch).roles;\n      } catch {\n        return undefined;\n      }\n    },\n    onConfigured(agent, data) {\n      appendEvent(agent, \"odai/output-configured\", data);\n    },\n  }));\n  ctx.tools.register(createCompactionConfigTool(config.compaction.configPath, {\n    isChild: isSubagent,\n    resolveCallConfig(route: ModelRoute, signal?: AbortSignal) {\n      return ctx.llm.resolveCallConfig(route, signal);\n    },\n    onConfigured(agent, data) {\n      appendEvent(agent, \"odai/compaction-configured\", data);\n    },\n  }));\n  ctx.tools.register(createSemanticMemoryTool(config.memory.storePath, {\n    configuredMode: config.memory.mode,\n    onChanged(agent, data) {\n      appendEvent(agent, \"odai/memory-changed\", data);\n    },\n  }));\n  ctx.tools.register(createHumanSafetyContinuityTool({\n    storePath: humanSafetyContinuityStorePath,\n    directUserTextFor(agent: DshAgent) {\n      const message = latestDirectUserMessage(agent);\n      return message ? extractLatestUserText([message]) : \"\";\n    },\n    onChanged(agent, data) {\n      appendEvent(agent, \"odai/human-safety-continuity-changed\", data);\n    },\n  }));\n  const repeatedFailure = createRepeatedFailureMonitor({\n    taskFor(agent) {\n      const id = latestDirectUserMessage(agent)?.id;\n      return typeof id === \"string\" ? id : undefined;\n    },\n    onRepeated({ agent }, notice) {\n      agent.inject?.(pluginMessage(notice, \"Repeated command outcomes: review whether another retry is useful\"));\n    },\n  });\n  ctx.tools.guard?.((execution: ToolExecution) => {\n    const agent = execution.agent;\n    if (agent && !isSubagentSession(agent) && config.routing.mode !== \"off\" && !responsibilityScopes.get(agent)) {\n      const events = evidence.events(agent);\n      const consumed = new Set(events.filter(event => event.type === \"odai/responsibility-gap-consumed\").map(event => event.data.stateDigest));\n      const message = latestDirectUserMessage(agent);\n      const taskId = message && leadTaskId(events, message.id, classifyPendingReviewerText(extractLatestUserText([message])) === \"continue\");\n      const state = leadState(events);\n      if (taskId && state?.enabled && Array.isArray(state.roles) && state.roles.includes(\"planner\") && isLeadWriteTool(execution.name)) {\n        const existing = events.some(event => event.type === \"odai/responsibility-gap\" && event.data.taskMessageId === taskId && event.data.responsibility === \"planner\" && event.data.timing === \"start\");\n        if (!existing) {\n          appendEvent(agent, \"odai/responsibility-gap\", leadGap(\"planner\", taskId, currentAgentTurn(agent), currentAgentStep(agent) ?? 0));\n          return \"ODAI_NAMED_START_PENDING: 主导模式已登记规划请求，正在等待职责调度，不是渠道故障。此工具尚未执行；请停止重试工具并结束当前回复，让运行时调度规划。规划回交后由控制器继续原任务。\";\n        }\n      }\n      if (events.some(event => event.type === \"odai/responsibility-gap\" && event.data.userNamed === true && event.data.timing === \"start\" && !consumed.has(event.data.stateDigest))) {\n        const reason = \"ODAI_NAMED_START_PENDING: 职责请求已登记，正在等待调度，不是渠道故障。此工具尚未执行；请停止重试工具并结束当前回复，让运行时调度职责。职责回交后由控制器继续原任务。\";\n        onDenied({ ...execution, agent }, reason);\n        return reason;\n      }\n    }\n    if (execution.agent && isManagedReviewer(execution.agent) && !reviewerAllowedTools.includes(execution.name)) {\n      const reason = \"ODAI_REVIEW_READ_ONLY: managed reviewers may only inspect delegated source with read, glob, grep, and immutable evidence with odai_review_evidence\";\n      onDenied({ ...execution, agent: execution.agent }, reason);\n      return reason;\n    }\n    return childGuard(execution) ?? routeProtectionGuard(execution) ?? repeatedFailure.start(execution);\n  });\n\n  const toolExposureStates = new WeakMap<DshAgent, { readonly key: string; readonly dispose?: () => void }>();\n  const syncToolExposure = (\n    agent: DshAgent,\n    activation: ContextActivation,\n    options: ExposureOptions = {},\n  ): readonly string[] => {\n    const child = isSubagentSession(agent);\n    const policy = executionRestrictionFor(agent);\n    const activeNames = activeOdaiToolNames(activation, {\n      child,\n      responsibilityReturn: options.responsibilityReturn === true || isReadOnlyResponsibility(agent),\n      reviewEvidence: child && Boolean(managedReviewEvidenceReader(agent)),\n      responsibilityRouting: child || responsibilityRoutingFor(agent, options.turn),\n    }).filter((name) => (!policy.allow || policy.allow.includes(name)) && !policy.deny?.includes(name));\n    const deniedNames = [\n      ...inactiveOdaiToolNames(activeNames),\n      ...ODAI_CORE_TOOL_NAMES.filter((name) => !activeNames.includes(name)),\n      ...(policy.deny ?? []),\n    ];\n    // Include effective permissions: ending a scope must restore the controller\n    // even when its contextual capabilities have not changed.\n    const key = JSON.stringify([policy.allow ?? null, deniedNames]);\n    const previous = toolExposureStates.get(agent);\n    if (previous?.key === key) return activeNames;\n    previous?.dispose?.();\n    const agentTools = agent.ctx?.tools;\n    const restrict = agentTools?.restrict;\n    if (typeof restrict !== \"function\") {\n      toolExposureStates.set(agent, Object.freeze({ key }));\n      return activeNames;\n    }\n    try {\n      const restriction = deniedNames.length > 0 || policy.allow\n        ? restrict.call(agentTools, { ...policy, deny: deniedNames })\n        : undefined;\n      const dispose = typeof restriction === \"function\" ? restriction : undefined;\n      toolExposureStates.set(agent, Object.freeze({ key, dispose }));\n      appendEvent(agent, \"odai/tool-exposure-selected\", {\n        ...(options.turn === undefined ? {} : { turn: options.turn }),\n        ...(options.step === undefined ? {} : { step: options.step }),\n        mode: \"adaptive\",\n        activeTools: activeNames,\n      });\n    } catch (error) {\n      logger.warn(`Odai adaptive registry restriction is unavailable; prompt filtering and execution guards remain active: ${error instanceof Error ? error.message : String(error)}`);\n      toolExposureStates.set(agent, Object.freeze({ key }));\n    }\n    return activeNames;\n  };\n\n  // Native pre-step producers (including the skill catalog) inspect the scoped\n  // registry before prompt assembly. Restrict inherited child tools at creation.\n  ctx.on(\"agent/created\", ({ agent }: { agent: DshAgent }) => {\n    if (!isSubagentSession(agent)) return;\n    agent.ctx?.tools?.restrict?.(executionRestrictionFor(agent));\n  });\n\n  promptRuntime.install({ pendingResponsibilityGap, syncToolExposure, executionRestrictionFor });\n\n  ctx.on(\"tools/result\", (execution: ToolExecution, result: ToolResult) => {\n    if (!execution.agent) return;\n    const agent = execution.agent;\n    if (!isSubagentSession(agent) && config.routing.mode !== \"off\" && !responsibilityScopes.get(agent) && leadState(evidence.events(agent))?.enabled && isLeadWriteTool(execution.name) && !result.isError) {\n      const message = latestDirectUserMessage(agent);\n      if (message) appendEvent(agent, \"odai/lead-write\", { callId: execution.callId, tool: execution.name, taskMessageId: leadTaskId(evidence.events(agent), message.id, classifyPendingReviewerText(extractLatestUserText([message])) === \"continue\") });\n    }\n    const summary = summarizeToolResult(execution, result);\n    if (hasSessionEvent(execution.agent, \"odai/tool-observed\", (data) => data?.callId === summary.callId)) return;\n    repeatedFailure.observe(execution, result);\n    appendEvent(execution.agent, \"odai/tool-observed\", summary);\n  });\n\n\n}\n"
    },
    {
      "path": "dsh/runtime/src/control-center-runtime.mts",
      "content": "import { discoverCliModels } from \"./local-cli-catalog.mjs\";\nimport { applySessionControl, type SessionControlsSnapshot } from \"./session-controls.mjs\";\nimport {\n  applyRoutingConfigAction,\n  type RoleDispatches,\n  type RoleRoutes,\n  type RoutingConfigResult,\n} from \"./routing-config.mjs\";\nimport {\n  readStoredSessionEvidence,\n  resolveSessionEvidenceRoot,\n  storedSessionEvidenceRevision,\n} from \"./session-evidence.mjs\";\nimport type { SessionEvidenceEvent } from \"./session-evidence.mjs\";\nimport type { DshRuntimeContext, RuntimeLogger, UnknownRecord } from \"./runtime-types.mjs\";\nimport { isUnknownRecord } from \"./runtime-types.mjs\";\n\nconst CONTROL_CENTER_CHANNEL = \"/odai-control-center\";\nconst CONTROL_CENTER_ENDPOINT = \"routing\";\nconst CONTROL_CENTER_EVIDENCE_ENDPOINT = \"evidence\";\nconst CONTROL_CENTER_SESSION_ENDPOINT = \"session\";\nconst MAX_EVIDENCE_EVENTS = 2_000;\n\ninterface RpcFailure {\n  code: \"bad-request\" | \"route-rejected\" | \"unavailable\" | \"internal\";\n  message: string;\n}\n\nexport interface ControlCenterResponse {\n  ok: boolean;\n  session?: SessionControlsSnapshot;\n  choices?: Array<{ id: string; name: string }>;\n  config?: Omit<RoutingConfigResult, \"configPath\" | \"latestRoute\">;\n  events?: readonly SessionEvidenceEvent[];\n  revision?: string;\n  unchanged?: boolean;\n  error?: RpcFailure;\n}\n\ninterface ConnectionRpcResult {\n  ok: true;\n  value: ControlCenterResponse;\n}\n\ninterface HostConnectionRpc {\n  handle(\n    channel: string,\n    handler: (endpoint: string, payload: unknown, signal: AbortSignal) => Promise<ConnectionRpcResult>,\n    options: { authority: \"loopback\" },\n  ): () => Promise<void>;\n}\n\ninterface HostConnection {\n  rpc: HostConnectionRpc;\n  fetch?: {\n    register(route: { path: string; methods: string[]; requestBody: \"buffered\"; fetch(request: Request): Promise<Response> }): () => void | Promise<void>;\n  };\n}\n\nfunction registerControlCenter(connection: HostConnection,\n  handler: (endpoint: string, payload: unknown, signal: AbortSignal) => Promise<ConnectionRpcResult>,\n): () => Promise<void> {\n  if (!connection.fetch) return connection.rpc.handle(CONTROL_CENTER_CHANNEL, handler, { authority: \"loopback\" });\n  const disposers = [CONTROL_CENTER_ENDPOINT, CONTROL_CENTER_EVIDENCE_ENDPOINT, CONTROL_CENTER_SESSION_ENDPOINT].map((endpoint) => {\n    const method = `${CONTROL_CENTER_CHANNEL.slice(1)}/${endpoint}`;\n    return connection.fetch!.register({\n      path: `/api/${method}`, methods: [\"POST\"], requestBody: \"buffered\",\n      async fetch(request) {\n        let body: unknown;\n        try { body = await request.json(); } catch { return new Response(\"body is not JSON\", { status: 400 }); }\n        if (!isUnknownRecord(body) || body.type !== \"client-request\" || typeof body.rpcId !== \"string\"\n          || body.rpcId.length === 0 || body.method !== method) return new Response(\"invalid RPC envelope\", { status: 400 });\n        return Response.json({ type: \"server-response\", rpcId: body.rpcId,\n          result: await handler(endpoint, body.payload, request.signal) });\n      },\n    });\n  });\n  return async () => { for (const dispose of disposers) await dispose(); };\n}\n\ninterface SharedRegistration {\n  owners: Map<symbol, ControlCenterRuntimeOptions>;\n  dispose: () => Promise<void>;\n}\n\ninterface SharedControlCenterState {\n  registration?: SharedRegistration;\n}\n\ntype ControlCenterGlobal = typeof globalThis & {\n  __odaiControlCenterRpc?: SharedControlCenterState;\n};\n\nexport interface ControlCenterRuntimeOptions {\n  configPath: string;\n  routingMode?: string;\n  evidenceRoot?: string;\n  configuredRoles?: Readonly<RoleRoutes>;\n  configuredDispatch?: Readonly<RoleDispatches>;\n  logger?: RuntimeLogger;\n}\n\nfunction effectiveOptions(owners: ReadonlyMap<symbol, ControlCenterRuntimeOptions>): ControlCenterRuntimeOptions {\n  let selected: ControlCenterRuntimeOptions | undefined;\n  let selectedWeight = -1;\n  for (const options of owners.values()) {\n    const weight = Object.keys(options.configuredRoles ?? {}).length\n      + Object.keys(options.configuredDispatch ?? {}).length;\n    if (selected === undefined || weight > selectedWeight\n      || (weight === selectedWeight && selected.routingMode === undefined && options.routingMode !== undefined)) {\n      selected = options;\n      selectedWeight = weight;\n    }\n  }\n  if (!selected) throw new Error(\"Control Center RPC has no active runtime owner\");\n  return selected;\n}\n\nfunction connectionFrom(ctx: DshRuntimeContext): HostConnection | undefined {\n  // Property access retains Cordis's injected caller; reflect.get may bind the service's owner instead.\n  const candidate = ctx.inject\n    ? (ctx as DshRuntimeContext & { connection?: unknown }).connection\n    : ctx.get?.(\"connection\");\n  if (!isUnknownRecord(candidate) || !isUnknownRecord(candidate.rpc)\n    || typeof candidate.rpc.handle !== \"function\") return undefined;\n  return candidate as unknown as HostConnection;\n}\n\nfunction publicResult(result: RoutingConfigResult): Omit<RoutingConfigResult, \"configPath\" | \"latestRoute\"> {\n  const visible: Partial<RoutingConfigResult> = { ...result };\n  delete visible.configPath;\n  delete visible.latestRoute;\n  return visible as Omit<RoutingConfigResult, \"configPath\" | \"latestRoute\">;\n}\n\nfunction evidenceRequest(payload: unknown): { sessionId: string; revision?: string } {\n  if (!isUnknownRecord(payload) || Object.keys(payload).some((key) => key !== \"sessionId\" && key !== \"revision\")\n    || typeof payload.sessionId !== \"string\" || payload.sessionId === \"\" || payload.sessionId.length > 512\n    || (payload.revision !== undefined && (typeof payload.revision !== \"string\" || payload.revision.length > 128))) {\n    throw new TypeError(\"evidence request requires a non-empty sessionId and optional revision\");\n  }\n  return {\n    sessionId: payload.sessionId,\n    ...(typeof payload.revision === \"string\" ? { revision: payload.revision } : {}),\n  };\n}\n\nfunction failureFor(error: unknown): RpcFailure {\n  const message = error instanceof Error ? error.message : String(error);\n  const code = isUnknownRecord(error) && typeof error.code === \"string\"\n    ? error.code.toUpperCase()\n    : \"\";\n  if (code || /responsibility route rejected/iu.test(message)) {\n    return { code: \"route-rejected\", message };\n  }\n  if (error instanceof TypeError) return { code: \"bad-request\", message };\n  return { code: \"internal\", message };\n}\n\nexport function installControlCenterRuntimeWhenAvailable(\n  ctx: DshRuntimeContext,\n  options: ControlCenterRuntimeOptions,\n): () => Promise<void> {\n  let release: (() => Promise<void>) | undefined;\n  let stopped = false;\n  if (ctx.inject) {\n    const binding = ctx.inject([\"connection\", \"webServer\"], (available) => {\n      if (stopped) return;\n      const mounted = installControlCenterRuntime(available, options);\n      release = mounted;\n      available.effect?.(() => async () => {\n        if (release === mounted) release = undefined;\n        await mounted?.();\n      }, \"odai: Control Center transport ownership\");\n    });\n    return async () => {\n      stopped = true;\n      await binding.dispose();\n      const current = release;\n      release = undefined;\n      await current?.();\n    };\n  }\n  const mount = (): void => {\n    if (stopped || release) return;\n    release = installControlCenterRuntime(ctx, options);\n  };\n  ctx.on(\"internal/service\", (serviceName: string) => {\n    if (serviceName === \"connection\") mount();\n  });\n  mount();\n  return async () => {\n    stopped = true;\n    const current = release;\n    release = undefined;\n    await current?.();\n  };\n}\n\nexport function installControlCenterRuntime(\n  ctx: DshRuntimeContext,\n  options: ControlCenterRuntimeOptions,\n): (() => Promise<void>) | undefined {\n  const connection = connectionFrom(ctx);\n  if (!connection) {\n    options.logger?.info(\"Control Center RPC unavailable outside a DSH client-connection host\");\n    return undefined;\n  }\n\n  const root = globalThis as ControlCenterGlobal;\n  const shared = root.__odaiControlCenterRpc ??= {};\n  const owner = Symbol(\"odai-control-center-owner\");\n  const releaseOwner = async (registration: SharedRegistration): Promise<void> => {\n    registration.owners.delete(owner);\n    if (registration.owners.size > 0 || shared.registration !== registration) return;\n    delete shared.registration;\n    await registration.dispose();\n  };\n  const existing = shared.registration;\n  if (existing) {\n    existing.owners.set(owner, options);\n    let released = false;\n    return async () => {\n      if (released) return;\n      released = true;\n      await releaseOwner(existing);\n    };\n  }\n\n  const owners = new Map<symbol, ControlCenterRuntimeOptions>([[owner, options]]);\n  const dispose = registerControlCenter(connection, async (endpoint, payload, signal) => {\n    if (endpoint !== CONTROL_CENTER_ENDPOINT && endpoint !== CONTROL_CENTER_EVIDENCE_ENDPOINT && endpoint !== CONTROL_CENTER_SESSION_ENDPOINT) {\n      return { ok: true, value: { ok: false, error: { code: \"unavailable\", message: \"unknown Odai Control Center endpoint\" } } };\n    }\n    const active = effectiveOptions(owners);\n    try {\n      if (endpoint === CONTROL_CENTER_ENDPOINT && isUnknownRecord(payload) && payload.action === \"choices\") {\n        if (typeof payload.cli === \"string\") return { ok: true, value: { ok: true, choices: await discoverCliModels(payload.cli, signal) } };\n        const llm = ctx.llm as unknown as {\n          listProviders?(): Array<{ id: string; name: string }>;\n          listModels?(provider: string): Promise<Array<{ id: string; name: string }>>;\n          resolveModelInfo?(provider: string, model: string, signal?: AbortSignal): Promise<{ reasoning?: { efforts: Array<{ id: string; name: string }> } }>;\n        };\n        if (!llm?.listProviders) throw new TypeError(\"宿主未提供模型目录，请手动输入\");\n        if (payload.provider !== undefined && typeof payload.provider !== \"string\") throw new TypeError(\"invalid provider\");\n        if (payload.model !== undefined && typeof payload.model !== \"string\") throw new TypeError(\"invalid model\");\n        let choices;\n        if (typeof payload.provider !== \"string\" || !payload.provider) choices = llm.listProviders();\n        else if (typeof payload.model !== \"string\" || !payload.model) {\n          if (!llm.listModels) throw new TypeError(\"宿主未提供模型列表，请手动输入\");\n          choices = await llm.listModels(payload.provider);\n        } else {\n          if (!llm.resolveModelInfo) throw new TypeError(\"宿主未提供推理档位，请手动输入\");\n          choices = (await llm.resolveModelInfo(payload.provider, payload.model, signal)).reasoning?.efforts ?? [];\n        }\n        return { ok: true, value: { ok: true, choices: choices.map(({ id, name }) => ({ id, name })) } };\n      }\n      if (endpoint === CONTROL_CENTER_SESSION_ENDPOINT) return { ok: true, value: { ok: true, session: applySessionControl(payload, { ...active, evidenceRoot: active.evidenceRoot ?? resolveSessionEvidenceRoot(active.configPath) }) } };\n      if (endpoint === CONTROL_CENTER_EVIDENCE_ENDPOINT) {\n        const request = evidenceRequest(payload);\n        const evidenceRoot = active.evidenceRoot ?? resolveSessionEvidenceRoot(active.configPath);\n        const revision = storedSessionEvidenceRevision(evidenceRoot, request.sessionId);\n        if (request.revision === revision) {\n          return { ok: true, value: { ok: true, revision, unchanged: true } };\n        }\n        const events = readStoredSessionEvidence(\n          evidenceRoot,\n          request.sessionId,\n          { warn: (message) => active.logger?.warn(message) },\n        ).slice(-MAX_EVIDENCE_EVENTS);\n        return { ok: true, value: { ok: true, events, revision, unchanged: false } };\n      }\n      const config = await applyRoutingConfigAction(active.configPath, payload, {\n        configuredRoles: active.configuredRoles,\n        configuredDispatch: active.configuredDispatch,\n        resolveCallConfig: (route, callSignal) => ctx.llm.resolveCallConfig(route as UnknownRecord, callSignal),\n        signal,\n      });\n      return { ok: true, value: { ok: true, config: publicResult(config) } };\n    } catch (error) {\n      active.logger?.warn(`Control Center routing request failed: ${error instanceof Error ? error.message : String(error)}`);\n      return { ok: true, value: { ok: false, error: failureFor(error) } };\n    }\n  });\n  const registration: SharedRegistration = { owners, dispose };\n  shared.registration = registration;\n\n  let released = false;\n  return async () => {\n    if (released) return;\n    released = true;\n    await releaseOwner(registration);\n  };\n}\n\nexport { CONTROL_CENTER_CHANNEL, CONTROL_CENTER_ENDPOINT, CONTROL_CENTER_EVIDENCE_ENDPOINT };\n"
    },
